1	import { Client, type ClientChannel } from "ssh2";
2	
3	/**
4	 * READ-ONLY source auto-detection for the migration wizard.
5	 *
6	 * Given SSH credentials for a customer-specified SOURCE box, we open a single
7	 * password-authenticated SSH session and *look* at what is there — web roots,
8	 * home directories, database engines AND what is actually RUNNING (Docker
9	 * containers, listening ports, app processes and their working directories,
10	 * signature-bearing app dirs under /opt·/srv·/app, non-distro services) — so the
11	 * wizard can present a pre-checked "here's what we found" checklist instead of
12	 * making the customer type paths and DB names by hand. All of the running-app
13	 * discovery uses ONLY read-only probes: `docker ps`, `ss`/`netstat -lntp`, `ps`,
14	 * `readlink /proc/<pid>/cwd`, `du`, `[ -f ]`/`[ -d ]` tests and
15	 * `systemctl list-units` — no writes, installs or state changes, still fixed and
16	 * input-free (only constant shell globs the REMOTE shell expands), still capped
17	 * and timeout-bounded. Names/paths that come back are re-validated against the
18	 * same allowlists before any can be selected for transfer.
19	 *
20	 * SECURITY — the source is UNTRUSTED and customer-supplied, so this mirrors the
21	 * hardening in worker/migrate-real.ts:
22	 *
23	 *   1. The scan is strictly READ-ONLY. Every probe is a fixed, input-free shell
24	 *      script (directory globs are expanded by the REMOTE shell from constant
25	 *      patterns — no customer value is ever interpolated into it). We never
26	 *      write, install or modify anything on the source. Database listing reads
27	 *      its credentials file from `/dev/stdin`, so not even a temp file is
28	 *      written to the source.
29	 *
30	 *   2. SECRETS NEVER TOUCH A COMMAND STRING. The SSH password is handed to the
31	 *      ssh2 transport, never a shell. DB credentials are streamed into the far
32	 *      command's STDIN (a `[client]` defaults file / a `.pgpass` line consumed
33	 *      via `/dev/stdin`), never as an argv token.
34	 *
35	 *   3. STRICT ALLOWLIST VALIDATION. Host / port / SSH user / DB user are checked
36	 *      against shell-inert allowlists before use — we reject, never sanitize.
37	 *      Paths and DB names that come BACK from the source are re-validated against
38	 *      the same allowlist the real engine enforces; anything that doesn't match
39	 *      is dropped (it could not be migrated safely anyway).
40	 *
41	 *   4. Everything is timeout-bounded and size/count-capped.
42	 */
43	
44	// ---- Result shapes (no secrets ever) --------------------------------------
45	export type WebAppType = "wordpress" | "laravel" | "django" | "node" | "php" | "unknown";
46	
47	export type DetectedWebRoot = { path: string; sizeLabel: string; appType: WebAppType };
48	export type DetectedHome = { path: string; sizeLabel: string };
49	export type DetectedDatabase = { engine: "mysql" | "postgres"; name: string; sizeLabel: string };
50	export type DetectedEngine = {
51	  engine: "mysql" | "postgres";
52	  present: boolean;
53	  listening: boolean;
54	  listed: boolean; // did we successfully enumerate databases with the given creds?
55	};
56	
57	// The runtime that pointed us at a candidate app directory (or "unknown" when a
58	// directory scan found app signatures without a matching running process).
59	export type AppRuntime =
60	  | "node"
61	  | "python"
62	  | "java"
63	  | "ruby"
64	  | "php-fpm"
65	  | "pm2"
66	  | "next"
67	  | "dotnet"
68	  | "unknown";
69	// The on-disk signature that marks a directory as an app worth migrating.
70	export type AppDirSignature =
71	  | "wordpress"
72	  | "laravel"
73	  | "django"
74	  | "node"
75	  | "php"
76	  | "compose"
77	  | "python"
78	  | "git-repo"
79	  | "unknown";
80	
81	/** A candidate app directory discovered OUTSIDE the standard web roots — either a
82	 *  running process's cwd (#3) or a signature-bearing dir under /opt, /srv, /app… (#4). */
83	export type DetectedAppDir = {
84	  path: string;
85	  sizeLabel: string;
86	  runtime: AppRuntime;
87	  signature: AppDirSignature;
88	};
89	/** A running Docker container. `mounts` are the bind-mount host paths (the data to
90	 *  migrate); named volumes appear here too but are not absolute paths. */
91	export type DetectedContainer = {
92	  name: string;
93	  image: string;
94	  ports: string;
95	  mounts: string[];
96	};
97	/** A listening TCP socket + owning process, with a friendly role guess. Informational. */
98	export type DetectedPort = { port: number; proc: string; role: string };
99	/** A running non-distro systemd service — name only, as a hint. Informational. */
100	export type DetectedService = { name: string };
101	
102	export type ScanResult = {
103	  ok: boolean;
104	  webRoots: DetectedWebRoot[];
105	  homes: DetectedHome[];
106	  databases: DetectedDatabase[];
107	  engines: DetectedEngine[];
108	  // Running-app discovery (all read-only, informational except appDirs which are
109	  // migratable paths that get merged into the copy list, deduped against webRoots/homes).
110	  appDirs: DetectedAppDir[];
111	  containers: DetectedContainer[];
112	  ports: DetectedPort[];
113	  services: DetectedService[];
114	  notes: string[];
115	  synthetic?: boolean;
116	};
117	
118	export type DetectInput = {
119	  host: string;
120	  port: number;
121	  user: string;
122	  password: string;
123	  /** Optional DB admin creds — only then can we enumerate database names/sizes. */
124	  dbUser?: string;
125	  dbPassword?: string;
126	};
127	
128	// ---- Timeouts / caps ------------------------------------------------------
129	const CONNECT_TIMEOUT_MS = 20_000;
130	const SCAN_TIMEOUT_MS = 75_000; // the big du/probe sweep
131	const DB_TIMEOUT_MS = 25_000;
132	const MAX_WEB_ROOTS = 40;
133	const MAX_HOMES = 40;
134	const MAX_DATABASES = 60;
135	const MAX_APP_DIRS = 40;
136	const MAX_CONTAINERS = 30;
137	const MAX_PORTS = 60;
138	const MAX_SERVICES = 30;
139	
140	// ---- Strict allowlist validators (mirror worker/migrate-real.ts) ----------
141	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
142	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
143	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
144	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
145	const DBUSER_RE = /^[A-Za-z0-9_]{1,64}$/;
146	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/;
147	// MUST match IDENT_RE in worker/migrate-real.ts — only surface DB names the real
148	// transfer engine can actually migrate, so nothing selected here fails later.
149	const DBNAME_RE = /^[A-Za-z0-9_]{1,64}$/;
150	// Informational identifiers that come BACK from the source. These are never used
151	// in a shell or selected for transfer — only rendered as text — but we still keep
152	// them shell-inert and bounded so nothing weird flows through.
153	const CONTNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
154	const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;
155	
156	/** Strip control chars, trim and bound the length of any free text from the source. */
157	function cleanText(s: string, max: number): string {
158	  // eslint-disable-next-line no-control-regex
159	  return (s ?? "").replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, max);
160	}
161	
162	// Well-known listening ports → a friendly role label for the "what's running" summary.
163	const PORT_ROLES: Record<number, string> = {
164	  21: "ftp",
165	  22: "ssh",
166	  25: "mail",
167	  80: "web",
168	  110: "mail",
169	  143: "mail",
170	  443: "web",
171	  465: "mail",
172	  587: "mail",
173	  993: "mail",
174	  3000: "app",
175	  3306: "mysql",
176	  4000: "app",
177	  5000: "app",
178	  5432: "postgres",
179	  5433: "postgres",
180	  5672: "rabbitmq",
181	  6379: "redis",
182	  8000: "app",
183	  8080: "app",
184	  8443: "web",
185	  9000: "app",
186	  9200: "elasticsearch",
187	  11211: "memcached",
188	  27017: "mongo",
189	};
190	function mapPortRole(p: number): string {
191	  return PORT_ROLES[p] ?? "other";
192	}
193	function mapRuntime(s: string): AppRuntime {
194	  switch (s) {
195	    case "node":
196	      return "node";
197	    case "python":
198	      return "python";
199	    case "java":
200	      return "java";
201	    case "ruby":
202	      return "ruby";
203	    case "phpfpm":
204	      return "php-fpm";
205	    case "pm2":
206	      return "pm2";
207	    case "next":
208	      return "next";
209	    case "dotnet":
210	      return "dotnet";
211	    default:
212	      return "unknown";
213	  }
214	}
215	function mapSignature(s: string): AppDirSignature {
216	  if (s === "gitrepo") return "git-repo";
217	  return (["wordpress", "laravel", "django", "node", "php", "compose", "python"] as AppDirSignature[]).includes(
218	    s as AppDirSignature
219	  )
220	    ? (s as AppDirSignature)
221	    : "unknown";
222	}
223	
224	function assert(cond: unknown, msg: string): asserts cond {
225	  if (!cond) throw new Error(msg);
226	}
227	function validHost(h: string): boolean {
228	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
229	}
230	function validPath(p: string): boolean {
231	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
232	}
233	
234	/** Collapse duplicate slashes and strip a trailing slash from a du-emitted path. */
235	function normalizeRemotePath(p: string): string {
236	  const collapsed = (p ?? "").replace(/\/{2,}/g, "/").replace(/\/+$/, "");
237	  return collapsed || "/";
238	}
239	
240	// ---- SSH plumbing (same shape as migrate-real.ts) -------------------------
241	function execRemote(
242	  conn: Client,
243	  cmd: string,
244	  timeoutMs: number
245	): Promise<{ code: number; stdout: string; stderr: string }> {
246	  return new Promise((resolve, reject) => {
247	    conn.exec(cmd, (err, stream: ClientChannel) => {
248	      if (err) return reject(err);
249	      let stdout = "";
250	      let stderr = "";
251	      const timer = setTimeout(() => {
252	        try {
253	          stream.close();
254	        } catch {
255	          /* ignore */
256	        }
257	        reject(new Error("remote command timed out"));
258	      }, timeoutMs);
259	      stream
260	        .on("close", (code: number) => {
261	          clearTimeout(timer);
262	          resolve({ code: code ?? 0, stdout, stderr });
263	        })
264	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
265	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
266	    });
267	  });
268	}
269	
270	/** Run a command, streaming `input` into its STDIN (secret goes here, never argv). */
271	function execRemoteInput(
272	  conn: Client,
273	  cmd: string,
274	  input: string,
275	  timeoutMs: number
276	): Promise<{ code: number; stdout: string; stderr: string }> {
277	  return new Promise((resolve, reject) => {
278	    conn.exec(cmd, (err, stream: ClientChannel) => {
279	      if (err) return reject(err);
280	      let stdout = "";
281	      let stderr = "";
282	      const timer = setTimeout(() => {
283	        try {
284	          stream.close();
285	        } catch {
286	          /* ignore */
287	        }
288	        reject(new Error("remote command timed out"));
289	      }, timeoutMs);
290	      stream
291	        .on("close", (code: number) => {
292	          clearTimeout(timer);
293	          resolve({ code: code ?? 0, stdout, stderr });
294	        })
295	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
296	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
297	      stream.end(input);
298	    });
299	  });
300	}
301	
302	function connectSource(input: DetectInput): Promise<Client> {
303	  return new Promise((resolve, reject) => {
304	    const conn = new Client();
305	    conn.on("ready", () => resolve(conn));
306	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
307	    conn.connect({
308	      host: input.host,
309	      port: input.port,
310	      username: input.user,
311	      password: input.password,
312	      readyTimeout: CONNECT_TIMEOUT_MS,
313	      // Password-only: never offer a local key to the untrusted source host.
314	      tryKeyboard: false,
315	    });
316	  });
317	}
318	
319	// ---- Helpers --------------------------------------------------------------
320	function humanBytes(n: number): string {
321	  if (!Number.isFinite(n) || n <= 0) return "0 B";
322	  const units = ["B", "KB", "MB", "GB", "TB"];
323	  let i = 0;
324	  let v = n;
325	  while (v >= 1024 && i < units.length - 1) {
326	    v /= 1024;
327	    i++;
328	  }
329	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
330	}
331	
332	/**
333	 * The read-only probe script. Deliberately input-free: the only variable parts
334	 * are constant shell globs expanded by the REMOTE shell, so there is no
335	 * injection surface. POSIX-sh only (works under `sh` or `bash`).
336	 */
337	// NOTE: authored as a plain string (not a template literal) so shell `${...}`
338	// parameter expansions can never collide with JS `${}` interpolation. Any
339	// trailing/duplicate slashes in emitted paths are normalized in JS below.
340	const SCAN_SCRIPT = [
341	  "export LC_ALL=C",
342	  'if command -v timeout >/dev/null 2>&1; then TO="timeout 25"; else TO=""; fi',
343	  "emit_web() {",
344	  "  d=$1",
345	  '  [ -d "$d" ] || return 0',
346	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1)',
347	  '  [ -n "$sz" ] || sz=\'?\'',
348	  "  t=unknown",
349	  '  if [ -f "$d/wp-config.php" ]; then t=wordpress',
350	  '  elif [ -f "$d/artisan" ]; then t=laravel',
351	  '  elif [ -f "$d/manage.py" ]; then t=django',
352	  '  elif [ -f "$d/package.json" ]; then t=node',
353	  '  elif [ -f "$d/composer.json" ]; then t=php',
354	  "  else",
355	  '    for f in "$d"/*.php; do [ -e "$f" ] && { t=php; break; }; done',
356	  "  fi",
357	  "  printf 'WEB\\t%s\\t%s\\t%s\\n' \"$t\" \"$sz\" \"$d\"",
358	  "}",
359	  // Emit a candidate app directory OUTSIDE the web roots (a process cwd or a
360	  // signature-bearing dir). $1=runtime hint, $2=dir. Read-only: du + [ -f ] tests
361	  // only. seen_cwd de-dups within a shell to avoid repeated du on the same dir.
362	  "seen_cwd=' '",
363	  "emit_appdir() {",
364	  "  rt=$1; d=$2",
365	  '  [ -d "$d" ] || return 0',
366	  '  case "$d" in /|/usr|/usr/*|/bin|/sbin|/lib|/lib/*|/lib64*|/etc|/etc/*|/proc*|/sys*|/dev*|/run*|/tmp|/tmp/*|/var/lib/docker*|/snap*) return 0;; esac',
367	  '  case "$seen_cwd" in *" $d "*) return 0;; esac',
368	  '  seen_cwd="$seen_cwd$d "',
369	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
370	  "  sig=unknown",
371	  '  if [ -f "$d/wp-config.php" ]; then sig=wordpress',
372	  '  elif [ -f "$d/artisan" ]; then sig=laravel',
373	  '  elif [ -f "$d/manage.py" ]; then sig=django',
374	  '  elif [ -f "$d/docker-compose.yml" ] || [ -f "$d/docker-compose.yaml" ] || [ -f "$d/compose.yml" ] || [ -f "$d/compose.yaml" ]; then sig=compose',
375	  '  elif [ -f "$d/requirements.txt" ]; then sig=python',
376	  '  elif [ -f "$d/package.json" ]; then sig=node',
377	  '  elif [ -f "$d/composer.json" ]; then sig=php',
378	  '  elif [ -d "$d/.git" ]; then sig=gitrepo',
379	  "  fi",
380	  "  printf 'APPDIR\\t%s\\t%s\\t%s\\t%s\\n' \"$rt\" \"$sig\" \"$sz\" \"$d\"",
381	  "}",
382	  'for d in /var/www/html /usr/share/nginx/html /var/www /srv/www; do emit_web "$d"; done',
383	  'for d in /var/www/*/ /srv/www/*/ /home/*/public_html; do emit_web "$d"; done',
384	  "for d in /home/*/; do",
385	  '  [ -d "$d" ] || continue',
386	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
387	  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" \"$d\"",
388	  "done",
389	  "if [ -d /root ]; then",
390	  "  sz=$($TO du -shx /root 2>/dev/null | cut -f1); [ -n \"$sz\" ] || sz='?'",
391	  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" /root",
392	  "fi",
393	  "mp=0; ml=0; pp=0; pl=0",
394	  "{ command -v mysqld >/dev/null 2>&1 || command -v mariadbd >/dev/null 2>&1 || command -v mysql >/dev/null 2>&1 || [ -d /var/lib/mysql ]; } && mp=1",
395	  "{ command -v pg_dump >/dev/null 2>&1 || command -v psql >/dev/null 2>&1 || [ -d /var/lib/postgresql ]; } && pp=1",
396	  "ports=$( (ss -H -lnt 2>/dev/null || netstat -lnt 2>/dev/null) )",
397	  "printf '%s\\n' \"$ports\" | grep -q ':3306[^0-9]' && ml=1",
398	  "printf '%s\\n' \"$ports\" | grep -q ':5432[^0-9]' && pl=1",
399	  "printf 'ENGINE\\tmysql\\t%s\\t%s\\n' \"$mp\" \"$ml\"",
400	  "printf 'ENGINE\\tpostgres\\t%s\\t%s\\n' \"$pp\" \"$pl\"",
401	  // ---- Running Docker containers (name/image/ports/mounts). Read-only `docker ps`
402	  // only; wrapped in $TO so an unresponsive daemon can't hang the probe. Cap 30. --
403	  "if command -v docker >/dev/null 2>&1; then",
404	  "  $TO docker ps --no-trunc --format '{{.Names}}|{{.Image}}|{{.Ports}}|{{.Mounts}}' 2>/dev/null | head -n 30 | while IFS= read -r dl; do",
405	  "    [ -n \"$dl\" ] && printf 'DOCKER\\t%s\\n' \"$dl\"",
406	  "  done",
407	  "fi",
408	  // ---- Listening TCP sockets + owning process (ss, fallback netstat). Read-only. --
409	  "lp=$( ($TO ss -H -lntp 2>/dev/null || $TO netstat -lntp 2>/dev/null) )",
410	  "printf '%s\\n' \"$lp\" | head -n 200 | while IFS= read -r pl; do",
411	  "  [ -n \"$pl\" ] && printf 'PORT\\t%s\\n' \"$pl\"",
412	  "done",
413	  // ---- App processes → their working directory (candidate app dirs). Read-only:
414	  // ps + readlink /proc/<pid>/cwd only; emit_appdir does the du/signature test. --
415	  "if command -v ps >/dev/null 2>&1; then",
416	  "  ps -eo pid=,comm= 2>/dev/null | head -n 400 | while read -r ppid pcomm; do",
417	  '    rt=""',
418	  '    case "$pcomm" in',
419	  "      node|nodejs) rt=node;;",
420	  "      python|python3|gunicorn|uvicorn|celery) rt=python;;",
421	  "      java) rt=java;;",
422	  "      ruby|puma|unicorn) rt=ruby;;",
423	  "      php-fpm*|php) rt=phpfpm;;",
424	  "      PM2*|pm2*) rt=pm2;;",
425	  "      next*|next-server*) rt=next;;",
426	  "      dotnet) rt=dotnet;;",
427	  "    esac",
428	  '    [ -n "$rt" ] || continue',
429	  '    cwd=$(readlink "/proc/$ppid/cwd" 2>/dev/null)',
430	  '    [ -n "$cwd" ] || continue',
431	  '    emit_appdir "$rt" "$cwd"',
432	  "  done",
433	  "fi",
434	  // ---- Signature-bearing app dirs under /opt, /srv, /app, home subdirs. Read-only. --
435	  "acount=0",
436	  "for d in /opt/*/ /srv/*/ /app /app/*/ /home/*/*/; do",
437	  '  [ -d "$d" ] || continue',
438	  '  case "$d" in /srv/www|/srv/www/*) continue;; esac',
439	  '  if [ -f "$d/package.json" ] || [ -f "$d/composer.json" ] || [ -f "$d/requirements.txt" ] || [ -f "$d/manage.py" ] || [ -f "$d/docker-compose.yml" ] || [ -f "$d/docker-compose.yaml" ] || [ -f "$d/compose.yml" ] || [ -f "$d/compose.yaml" ] || [ -d "$d/.git" ]; then',
440	  '    emit_appdir scan "$d"',
441	  '    acount=$((acount+1)); [ "$acount" -ge 60 ] && break',
442	  "  fi",
443	  "done",
444	  // ---- Running non-distro systemd services, name only, as hints. Read-only. --
445	  "if command -v systemctl >/dev/null 2>&1; then",
446	  "  $TO systemctl list-units --type=service --state=running --no-legend --plain 2>/dev/null | head -n 150 | while read -r unit rest; do",
447	  '    case "$unit" in',
448	  "      systemd*|dbus*|cron*|crond*|ssh*|sshd*|rsyslog*|syslog*|networkd*|resolved*|getty*|user@*|polkit*|accounts-daemon*|snapd*|multipathd*|udisks*|apparmor*|unattended*|packagekit*|chrony*|ntp*|thermald*|irqbalance*|atd*|acpid*) continue;;",
449	  "    esac",
450	  '    u=${unit%.service}',
451	  '    [ -n "$u" ] && printf \'SVC\\t%s\\n\' "$u"',
452	  "  done",
453	  "fi",
454	].join("\n");
455	
456	const SYSTEM_SCHEMAS = new Set(["information_schema", "performance_schema", "mysql", "sys"]);
457	
458	/** Parse a `du -sh`-style size label ("1.2G", "340M", "512K") into bytes for sorting. */
459	function parseSizeLabel(label: string): number {
460	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec(label.trim());
461	  if (!m) return 0;
462	  const n = parseFloat(m[1]);
463	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
464	  return n * (mult[m[2].toUpperCase()] ?? 1);
465	}
466	
467	// ---- Public entrypoint ----------------------------------------------------
468	/**
469	 * SSH into the source (read-only) and return a structured inventory. Throws only
470	 * on a fatal connection/auth failure; a source that is reachable but has (say) no
471	 * readable DB creds still returns a useful partial result with notes.
472	 */
473	export async function detectSource(input: DetectInput): Promise<ScanResult> {
474	  assert(validHost(input.host), "source host is not a valid hostname or IP address");
475	  assert(Number.isInteger(input.port) && input.port >= 1 && input.port <= 65535, "source SSH port is out of range");
476	  assert(USER_RE.test(input.user), "source SSH username contains unsupported characters");
477	  assert(input.password && input.password.length > 0, "source SSH password is required");
478	
479	  const notes: string[] = [];
480	  const webRoots: DetectedWebRoot[] = [];
481	  const homes: DetectedHome[] = [];
482	  const databases: DetectedDatabase[] = [];
483	  const engines: DetectedEngine[] = [];
484	  const rawAppDirs: DetectedAppDir[] = [];
485	  const containers: DetectedContainer[] = [];
486	  const ports: DetectedPort[] = [];
487	  const services: DetectedService[] = [];
488	  const seenPort = new Set<string>();
489	
490	  const conn = await connectSource(input);
491	  try {
492	    // ---- 1. Filesystem + engine probe (fixed, input-free, read-only) ------
493	    const scan = await execRemote(conn, SCAN_SCRIPT, SCAN_TIMEOUT_MS);
494	    const engineState: Record<"mysql" | "postgres", { present: boolean; listening: boolean }> = {
495	      mysql: { present: false, listening: false },
496	      postgres: { present: false, listening: false },
497	    };
498	
499	    for (const raw of scan.stdout.split("\n")) {
500	      const line = raw.replace(/\r$/, "");
501	      if (!line) continue;
502	      const parts = line.split("\t");
503	      if (parts[0] === "WEB" && parts.length >= 4) {
504	        const appType = parts[1] as WebAppType;
505	        const sizeLabel = parts[2] || "?";
506	        const path = normalizeRemotePath(parts[3]);
507	        if (!validPath(path)) continue;
508	        if (webRoots.some((w) => w.path === path)) continue;
509	        webRoots.push({
510	          path,
511	          sizeLabel,
512	          appType: (["wordpress", "laravel", "django", "node", "php"] as WebAppType[]).includes(appType)
513	            ? appType
514	            : "unknown",
515	        });
516	      } else if (parts[0] === "HOME" && parts.length >= 3) {
517	        const sizeLabel = parts[1] || "?";
518	        const path = normalizeRemotePath(parts[2]);
519	        if (!validPath(path)) continue;
520	        if (homes.some((h) => h.path === path)) continue;
521	        homes.push({ path, sizeLabel });
522	      } else if (parts[0] === "ENGINE" && parts.length >= 4) {
523	        const eng = parts[1] === "postgres" ? "postgres" : "mysql";
524	        engineState[eng] = { present: parts[2] === "1", listening: parts[3] === "1" };
525	      } else if (parts[0] === "APPDIR" && parts.length >= 5) {
526	        const sizeLabel = parts[3] || "?";
527	        const path = normalizeRemotePath(parts[4]);
528	        if (!validPath(path)) continue; // candidate for TRANSFER — must pass the strict allowlist
529	        rawAppDirs.push({
530	          path,
531	          sizeLabel,
532	          runtime: mapRuntime(parts[1]),
533	          signature: mapSignature(parts[2]),
534	        });
535	      } else if (parts[0] === "DOCKER") {
536	        // Line body is "name|image|ports|mounts" (never contains a tab, so parts[1] holds it whole).
537	        if (containers.length >= MAX_CONTAINERS) continue;
538	        const seg = (parts.slice(1).join("\t")).split("|");
539	        const name = cleanText(seg[0] ?? "", 128);
540	        if (!CONTNAME_RE.test(name)) continue; // shell-inert display id
541	        if (containers.some((c) => c.name === name)) continue;
542	        const mounts = (seg[3] ?? "")
543	          .split(",")
544	          .map((m) => cleanText(m, 256))
545	          .filter((m) => m.length > 0)
546	          .slice(0, 12);
547	        containers.push({
548	          name,
549	          image: cleanText(seg[1] ?? "", 200),
550	          ports: cleanText(seg[2] ?? "", 200),
551	          mounts,
552	        });
553	      } else if (parts[0] === "PORT") {
554	        if (ports.length >= MAX_PORTS) continue;
555	        const body = parts.slice(1).join("\t").trim();
556	        const toks = body.split(/\s+/);
557	        if (toks.length < 4) continue;
558	        const local = toks[3]; // ss and netstat both put the local addr:port at index 3
559	        const pm = /:(\d{1,5})$/.exec(local);
560	        if (!pm) continue;
561	        const portNum = Number(pm[1]);
562	        if (!Number.isInteger(portNum) || portNum < 1 || portNum > 65535) continue;
563	        // Owning process: ss ⇒ users:(("name",…  ;  netstat ⇒ trailing "pid/name".
564	        let proc = "";
565	        const ssm = /users:\(\("([^"]+)"/.exec(body);
566	        if (ssm) proc = ssm[1];
567	        else {
568	          const nsm = /\s(\d+)\/([^\s]+)\s*$/.exec(body);
569	          if (nsm) proc = nsm[2];
570	        }
571	        proc = cleanText(proc, 64);
572	        const dedup = `${portNum}/${proc}`;
573	        if (seenPort.has(dedup)) continue;
574	        seenPort.add(dedup);
575	        ports.push({ port: portNum, proc, role: mapPortRole(portNum) });
576	      } else if (parts[0] === "SVC" && parts.length >= 2) {
577	        if (services.length >= MAX_SERVICES) continue;
578	        const name = cleanText(parts[1], 128);
579	        if (!SVCNAME_RE.test(name)) continue;
580	        if (services.some((s) => s.name === name)) continue;
581	        services.push({ name });
582	      }
583	    }
584	
585	    // Prune web roots that are ancestors of another detected root (avoid copying
586	    // a parent AND its children — e.g. drop /var/www when /var/www/html exists).
587	    const pruned = webRoots.filter(
588	      (a) => !webRoots.some((b) => b.path !== a.path && b.path.startsWith(a.path + "/"))
589	    );
590	    webRoots.length = 0;
591	    webRoots.push(...pruned.slice(0, MAX_WEB_ROOTS));
592	    homes.splice(MAX_HOMES);
593	
594	    // Merge candidate app dirs into a migratable list, deduped against web roots /
595	    // home dirs (and each other) so a directory is never listed — or copied — twice.
596	    // A path clashes if it equals, contains, or is contained by an already-known path.
597	    const known = [...webRoots.map((w) => w.path), ...homes.map((h) => h.path)];
598	    const appDirs: DetectedAppDir[] = [];
599	    for (const a of rawAppDirs) {
600	      if (appDirs.length >= MAX_APP_DIRS) break;
601	      const clashesKnown = known.some(
602	        (p) => a.path === p || a.path.startsWith(p + "/") || p.startsWith(a.path + "/")
603	      );
604	      if (clashesKnown) continue;
605	      const clashesApp = appDirs.some(
606	        (b) => a.path === b.path || a.path.startsWith(b.path + "/") || b.path.startsWith(a.path + "/")
607	      );
608	      if (clashesApp) continue;
609	      appDirs.push(a);
610	    }
611	    appDirs.sort((x, y) => parseSizeLabel(y.sizeLabel) - parseSizeLabel(x.sizeLabel));
612	    if (appDirs.length > 0) {
613	      notes.push(
614	        `Found ${appDirs.length} app ${appDirs.length === 1 ? "directory" : "directories"} outside the standard web folders (from running processes / app files).`
615	      );
616	    }
617	    if (containers.length > 0) {
618	      notes.push(
619	        `Detected ${containers.length} running Docker ${containers.length === 1 ? "container" : "containers"} — we install Docker + Compose, copy their data and named volumes, and start any Compose project automatically on the new server.`
620	      );
621	    }
622	
623	    // ---- 2. Databases — only if the customer supplied DB creds ------------
624	    const hasSafePass =
625	      !!input.dbPassword && !input.dbPassword.includes("\n") && !input.dbPassword.includes("\r");
626	    if (input.dbPassword && !hasSafePass) {
627	      notes.push("Database password contains unsupported characters — databases were skipped.");
628	    }
629	
630	    for (const eng of ["mysql", "postgres"] as const) {
631	      const st = engineState[eng];
632	      const rec: DetectedEngine = { engine: eng, present: st.present, listening: st.listening, listed: false };
633	      if (st.present && hasSafePass) {
634	        const effUser = (input.dbUser && input.dbUser.trim()) || (eng === "mysql" ? "root" : "postgres");
635	        if (!DBUSER_RE.test(effUser)) {
636	          notes.push(`Database user "${effUser}" has unsupported characters — ${eng} databases were skipped.`);
637	        } else {
638	          try {
639	            const found =
640	              eng === "mysql"
641	                ? await listMysql(conn, effUser, input.dbPassword!)
642	                : await listPostgres(conn, effUser, input.dbPassword!);
643	            for (const d of found) {
644	              if (databases.length >= MAX_DATABASES) break;
645	              databases.push(d);
646	            }
647	            rec.listed = true;
648	          } catch (e: any) {
649	            notes.push(
650	              `${eng === "mysql" ? "MySQL" : "PostgreSQL"} is installed but we couldn't read its databases with those credentials — you can add databases manually.`
651	            );
652	          }
653	        }
654	      } else if (st.present && !input.dbPassword) {
655	        notes.push(
656	          `${eng === "mysql" ? "MySQL" : "PostgreSQL"} detected — all its databases are included automatically (no password needed; we dump them with root access on the old server).`
657	        );
658	      }
659	      engines.push(rec);
660	    }
661	
662	    databases.sort((a, b) => parseSizeLabel(b.sizeLabel) - parseSizeLabel(a.sizeLabel));
663	    ports.sort((a, b) => a.port - b.port);
664	
665	    return { ok: true, webRoots, homes, databases, engines, appDirs, containers, ports, services, notes };
666	  } finally {
667	    try {
668	      conn.end();
669	    } catch {
670	      /* best-effort */
671	    }
672	  }
673	}
