675	/** Enumerate MySQL/MariaDB schemas + sizes. Creds read from /dev/stdin (never argv). */
676	async function listMysql(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
677	  // `--defaults-extra-file=/dev/stdin` makes mysql read the [client] block from
678	  // the STDIN we stream below — the password never appears on the command line.
679	  const query =
680	    "SELECT table_schema, IFNULL(SUM(data_length+index_length),0) " +
681	    "FROM information_schema.tables GROUP BY table_schema;";
682	  const cnf = `[client]\nuser=${user}\npassword=${pass}\nhost=127.0.0.1\nprotocol=tcp\n`;
683	  const r = await execRemoteInput(
684	    conn,
685	    `mysql --defaults-extra-file=/dev/stdin -N -B -e ${shSingleQuote(query)}`,
686	    cnf,
687	    DB_TIMEOUT_MS
688	  );
689	  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `mysql exit ${r.code}`);
690	  const out: DetectedDatabase[] = [];
691	  for (const line of r.stdout.split("\n")) {
692	    const [name, bytes] = line.replace(/\r$/, "").split("\t");
693	    if (!name || SYSTEM_SCHEMAS.has(name.toLowerCase())) continue;
694	    if (!DBNAME_RE.test(name)) continue;
695	    out.push({ engine: "mysql", name, sizeLabel: humanBytes(Number(bytes) || 0) });
696	  }
697	  return out;
698	}
699	
700	/** Enumerate PostgreSQL databases + sizes. Creds read from /dev/stdin (.pgpass). */
701	async function listPostgres(conn: Client, user: string, pass: string): Promise<DetectedDatabase[]> {
702	  const query =
703	    "SELECT datname, pg_database_size(datname) FROM pg_database WHERE datistemplate = false;";
704	  const pgpass = `127.0.0.1:5432:*:${user}:${pass}\n`;
705	  const r = await execRemoteInput(
706	    conn,
707	    `PGPASSFILE=/dev/stdin psql -h 127.0.0.1 -U ${user} -w -A -t -F '\t' -c ${shSingleQuote(query)}`,
708	    pgpass,
709	    DB_TIMEOUT_MS
710	  );
711	  if (r.code !== 0) throw new Error(r.stderr.slice(0, 200) || `psql exit ${r.code}`);
712	  const out: DetectedDatabase[] = [];
713	  for (const line of r.stdout.split("\n")) {
714	    const [name, bytes] = line.replace(/\r$/, "").split("\t");
715	    if (!name || name === "postgres") continue;
716	    if (!DBNAME_RE.test(name)) continue;
717	    out.push({ engine: "postgres", name, sizeLabel: humanBytes(Number(bytes) || 0) });
718	  }
719	  return out;
720	}
721	
722	/**
723	 * Single-quote a FIXED, code-authored SQL string for the remote shell. The
724	 * inputs here are compile-time constants (never customer data), so this only
725	 * guards the literal `'` inside our own query text.
726	 */
727	function shSingleQuote(s: string): string {
728	  return `'${s.replace(/'/g, `'\\''`)}'`;
729	}
