11	export type { ScanResult } from "../worker/migrate-detect";
12	
13	/**
14	 * VPS migration — pull a customer's files + databases from another provider's
15	 * VPS onto their new Nxeon server. The customer supplies SSH credentials for the
16	 * SOURCE box; we only ever verify ownership of the TARGET (Nxeon) server.
17	 *
18	 * All source secrets (the SSH password and each database password) are encrypted
19	 * at rest with the shared AES-256-GCM box in lib/crypto-box.ts (`encryptSecret`),
20	 * the SAME helper used for mailbox/BYOK secrets. They are CLEARED by the worker
21	 * (worker/migrate.ts) the moment the migration finishes — success or failure —
22	 * so a completed Migration row never retains usable credentials. Nothing here
23	 * ever returns a decrypted secret (or the ciphertext) to the client.
24	 *
25	 * The heavy lifting runs in the `MIGRATE` worker job; this module only validates
26	 * input, encrypts secrets, records the Migration row and enqueues the job.
27	 */
28	
29	// ---- Input shapes (mirrors the Migration.items Json) ------------------------
30	
31	export type CreateMigrationInput = {
32	  serverId: string; // target Nxeon server (must be owned by the caller)
33	  sourceHost: string; // FQDN or IP of the source VPS
34	  sourcePort?: number; // SSH port, default 22
35	  sourceUser?: string; // SSH user, default "root" (we use root's LOCAL auth to dump DBs)
36	  sourcePassword: string; // SSH password for the source box
37	  paths?: string[]; // file paths to copy from the source (to the same paths on the target)
38	  /**
39	   * Read-only auto-detection snapshot (from scanSource). Carries NO secrets. We
40	   * derive the whole lift-and-shift plan (which DB engines to dump passwordlessly,
41	   * Docker volumes/compose dirs, prerequisites to install, ports to verify) from
42	   * it, and store both the plan and the snapshot under Migration.items — reusing
43	   * the existing Json column rather than adding a schema field (another agent
44	   * owns the schema this wave).
45	   */
46	  scan?: ScanResult;
47	};
48	
49	// The passwordless lift-and-shift plan, derived from the scan + selected paths and
50	// carried through Migration.items (secret-free). The worker re-validates every
51	// value against strict shell-inert allowlists before it is used in a command.
52	type MigrationPlan = {
53	  dbEngines: ("mysql" | "postgres")[];
54	  dockerVolumes: string[];
55	  composeDirs: string[];
56	  verifyPorts: number[];
57	  hasContainers: boolean;
58	  webServers: ("nginx" | "apache")[];
59	  runtimes: ("nodejs" | "python3")[];
60	};
61	
62	// ---- Client-safe row shapes (NEVER include secrets) -------------------------
63	
64	export type MigrationDatabaseView = {
65	  engine: string;
66	  name: string;
67	  user: string;
68	};
69	
70	export type MigrationRow = {
71	  id: string;
72	  serverId: string;
73	  serverName: string | null;
74	  sourceHost: string;
75	  sourcePort: number;
76	  sourceUser: string;
77	  paths: string[];
78	  databases: MigrationDatabaseView[];
79	  status: string;
80	  progress: number;
81	  step: string | null;
82	  log: string | null;
83	  lastError: string | null;
84	  createdAt: string;
85	  finishedAt: string | null;
86	};
87	
88	// ---- Validation -------------------------------------------------------------
89	
90	// Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
91	// (a bracketed/colon form is accepted) — the worker's SSH layer does the final
92	// resolution; this only rejects obvious junk before we store anything.
93	const HOST_RE =
94	  /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
95	const DEFAULT_PATHS = ["/var/www", "/home"];
96	const MAX_PATHS = 40;
97	
98	function cleanPaths(paths: string[] | undefined): string[] {
99	  const list = (paths && paths.length ? paths : DEFAULT_PATHS)
100	    .map((p) => p.trim())
101	    .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
102	  // De-dupe while preserving order.
103	  return [...new Set(list)].slice(0, MAX_PATHS);
104	}
105	
106	// Docker volume names are shell-inert (docker's own charset) — the worker
107	// re-validates, but we only ever store well-formed names.
108	const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
109	function isCopyableAbsPath(p: string): boolean {
110	  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
111	}
112	
113	/**
114	 * Derive the passwordless lift-and-shift plan from the read-only scan and the set
115	 * of paths the customer chose to copy. Databases are auto-included whenever an
116	 * engine was detected (no password needed — the worker dumps via root's local
117	 * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
118	 * can install them on the target. Everything here is secret-free.
119	 */
120	function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
121	  const empty: MigrationPlan = {
122	    dbEngines: [],
123	    dockerVolumes: [],
124	    composeDirs: [],
125	    verifyPorts: [],
126	    hasContainers: false,
127	    webServers: [],
128	    runtimes: [],
129	  };
130	  if (!scan || !scan.ok) return empty;
131	  const pathSet = new Set(selectedPaths);
132	
133	  // Auto-include every detected engine (dump passwordlessly via root local auth).
134	  const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
135	    (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
136	  );
137	
138	  const containers = scan.containers ?? [];
139	  // Named Docker volumes = container mounts that are NOT absolute host paths.
140	  const dockerVolumes = [
141	    ...new Set(
142	      containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
143	    ),
144	  ].slice(0, 60);
145	
146	  // Compose project dirs among the app dirs the customer is actually copying.
147	  const composeDirs = [
148	    ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
149	  ].slice(0, 40);
150	
151	  const verifyPorts = [
152	    ...new Set((scan.ports ?? []).map((p) => p.port).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22)),
153	  ].slice(0, 60);
154	
155	  const hasContainers = containers.length > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
156	
157	  // Web servers: match the owning process/service names, else default to nginx
158	  // when web roots exist (the overwhelmingly common case).
159	  const procBlob = [
160	    ...(scan.ports ?? []).map((p) => p.proc || ""),
161	    ...(scan.services ?? []).map((s) => s.name || ""),
162	  ]
163	    .join(" ")
164	    .toLowerCase();
165	  const webServers: ("nginx" | "apache")[] = [];
166	  if (/nginx/.test(procBlob)) webServers.push("nginx");
167	  if (/apache|httpd/.test(procBlob)) webServers.push("apache");
168	  if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");
169	
170	  // Runtimes: from running-app runtimes and listening-port owners. Conservative.
171	  const runtimeBlob = [
172	    ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
173	    ...(scan.ports ?? []).map((p) => p.proc || ""),
174	  ]
175	    .join(" ")
176	    .toLowerCase();
177	  const runtimes: ("nodejs" | "python3")[] = [];
178	  if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
179	  if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");
180	
181	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
182	}
