184	async function ownedTargetServer(serverId: string) {
185	  const user = await requireUser();
186	  const server = await db.server.findUnique({ where: { id: serverId } });
187	  if (!server) throw new Error("Not found");
188	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
189	  return { user, server };
