211	    paths?: string[];
212	    databases?: { engine?: string; name?: string; user?: string }[];
213	    dbEngines?: string[];
214	  };
215	  // Databases are now auto-included per detected engine (no per-DB list). For the
216	  // client view, surface one row per engine; fall back to any legacy per-DB list.
217	  const dbView: MigrationDatabaseView[] =
218	    Array.isArray(items.databases) && items.databases.length
219	      ? items.databases.map((d) => ({
