230	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
231	    // caller resolves the server row and passes it in.
232	    serverName: server ? server.label || server.hostname : null,
233	    sourceHost: m.sourceHost,
234	    sourcePort: m.sourcePort,
235	    sourceUser: m.sourceUser,
236	    paths: Array.isArray(items.paths) ? items.paths : [],
237	    // Never expose any DB secret — dbView carries only non-sensitive fields.
238	    databases: dbView,
239	    status: m.status,
240	    progress: m.progress,
241	    step: m.step,
242	    log: m.log,
