251	/**
252	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
253	 * ownership, validates the source connection details, encrypts every source
254	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
255	 * the new migration id; never returns any secret.
256	 */
257	export async function createMigration(
258	  input: CreateMigrationInput
259	): Promise<{ error?: string; id?: string }> {
260	  const { user, server } = await ownedTargetServer(input.serverId);
261	
262	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
263	  // credential-stuffing the wizard against arbitrary source hosts.
264	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
265	  if (!rl.ok) {
266	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
267	  }
268	
269	  const host = (input.sourceHost ?? "").trim();
270	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
271	    return { error: "Enter a valid source host — an IP address or domain name." };
272	  }
273	
274	  const port = input.sourcePort ?? 22;
275	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
276	    return { error: "SSH port must be between 1 and 65535." };
277	  }
278	
279	  const sourceUser = (input.sourceUser ?? "root").trim();
280	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
281	    return { error: "Enter the SSH username on the source server." };
282	  }
283	
284	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
285	    return { error: "Enter the SSH password for the source server." };
286	  }
287	
288	  const paths = cleanPaths(input.paths);
289	
290	  // Derive the passwordless lift-and-shift plan from the scan + selected paths.
291	  // Databases are auto-included when an engine is detected — no DB password is
292	  // ever collected; the worker dumps via root's local socket/peer auth.
293	  const plan = derivePlan(input.scan, paths);
294	
295	  // Persist the (secret-free) detection snapshot alongside the plan so the
296	  // migration is traceable back to what auto-detection found. Reusing items
297	  // avoids a schema change (Migration.items is a Json column).
298	  const scanSnapshot =
299	    input.scan && input.scan.ok
300	      ? {
301	          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
302	          homes: input.scan.homes?.slice(0, 40) ?? [],
303	          databases: input.scan.databases?.slice(0, 60) ?? [],
304	          engines: input.scan.engines ?? [],
305	          // Running-app discovery — informational, secret-free, for traceability.
306	          appDirs: input.scan.appDirs?.slice(0, 40) ?? [],
307	          containers: input.scan.containers?.slice(0, 30) ?? [],
308	          ports: input.scan.ports?.slice(0, 60) ?? [],
309	          services: input.scan.services?.slice(0, 30) ?? [],
310	          synthetic: !!input.scan.synthetic,
311	        }
312	      : undefined;
313	
314	  const items = {
315	    paths,
316	    dbEngines: plan.dbEngines,
317	    dockerVolumes: plan.dockerVolumes,
318	    composeDirs: plan.composeDirs,
319	    verifyPorts: plan.verifyPorts,
320	    hasContainers: plan.hasContainers,
321	    webServers: plan.webServers,
322	    runtimes: plan.runtimes,
323	    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
324	  };
325	
326	  const migration = await db.migration.create({
327	    data: {
328	      userId: user.id,
329	      serverId: server.id,
330	      sourceHost: host,
331	      sourcePort: port,
332	      sourceUser,
333	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
334	      items,
335	      status: "PENDING",
336	      progress: 0,
337	      step: "Queued",
338	    },
339	  });
340	
341	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
342	  // traceability); the handler loads everything else from payload.migrationId.
343	  await db.job.create({
344	    data: {
345	      type: "MIGRATE",
346	      serverId: server.id,
347	      payload: { migrationId: migration.id },
348	    },
349	  });
350	
351	  await db.auditLog.create({
352	    data: {
353	      userId: user.id,
354	      action: "migration.create",
355	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${plan.dbEngines.length} db engine(s), ${plan.composeDirs.length} compose)`,
356	    },
357	  });
358	
359	  revalidatePath("/dashboard/migrate");
360	  return { id: migration.id };
361	}
