363	/**
364	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
365	 * caller owns the TARGET server (authz + a stricter rate limit than create),
366	 * validates the source connection details, then SSHes into the source and
367	 * inventories web roots / home directories / databases — never writing anything
368	 * on the source and never persisting the supplied credentials.
369	 *
370	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
371	 * are NOT stored anywhere; the client re-supplies them to createMigration once
372	 * the customer confirms what to move. Returns a secret-free ScanResult.
373	 *
374	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
375	 * a real SSH connection, so staging stays fully self-contained.
376	 */
377	export async function scanSource(input: {
378	  serverId: string;
379	  sourceHost: string;
380	  sourcePort?: number;
381	  sourceUser?: string;
382	  sourcePassword: string;
383	  dbUser?: string;
384	  dbPassword?: string;
385	}): Promise<{ error?: string; scan?: ScanResult }> {
386	  const { user } = await ownedTargetServer(input.serverId);
387	
388	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
389	  // than migration creation to stop the wizard being used to probe hosts.
390	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
391	  if (!rl.ok) {
392	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
393	  }
394	
395	  const host = (input.sourceHost ?? "").trim();
396	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
397	    return { error: "Enter a valid source host — an IP address or domain name." };
398	  }
399	  const port = input.sourcePort ?? 22;
400	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
401	    return { error: "SSH port must be between 1 and 65535." };
402	  }
403	  const sourceUser = (input.sourceUser ?? "root").trim();
404	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
405	    return { error: "Enter the SSH username on the source server." };
406	  }
407	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
408	    return { error: "Enter the SSH password for the source server." };
409	  }
410	
411	  await db.auditLog.create({
412	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
413	  }).catch(() => {});
414	
415	  // SANDBOX: never touch the outside world — hand back synthetic detection.
416	  if (SANDBOX) {
417	    return { scan: syntheticScan({ dbPassword: input.dbPassword }) };
418	  }
419	
420	  // Hard overall timeout so a slow/hostile source can't hang the request.
421	  const HARD_TIMEOUT_MS = 90_000;
422	  try {
423	    const scan = await Promise.race<ScanResult>([
424	      detectSource({
425	        host,
426	        port,
427	        user: sourceUser,
428	        password: input.sourcePassword,
429	        dbUser: input.dbUser?.trim() || undefined,
430	        dbPassword: input.dbPassword || undefined,
431	      }),
432	      new Promise<ScanResult>((_, reject) =>
433	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
434	      ),
435	    ]);
436	    return { scan };
437	  } catch (e: any) {
438	    const msg = `${e?.message ?? e}`;
439	    // Map the common connection failures to friendly, non-leaky copy.
440	    if (/authentication|denied|password/i.test(msg)) {
441	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
442	    }
443	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
444	      return { error: "Couldn't reach the source server — check the host and SSH port." };
445	    }
446	    return { error: "We couldn't scan that server. Double-check the details and try again." };
447	  }
448	}
