240	 * Detect the package manager on the far side and return the install prefix, or
241	 * throw if none is supported. Fixed strings only — no user input.
242	 */
243	export async function pkgInstallPrefix(conn: Client): Promise<string> {
244	  const pm = await exec(
245	    conn,
246	    "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
247	      "elif command -v dnf >/dev/null 2>&1; then echo dnf; " +
248	      "elif command -v yum >/dev/null 2>&1; then echo yum; else echo none; fi",
249	    QUICK_TIMEOUT_MS
250	  );
251	  const which = pm.stdout.trim();
252	  if (which === "apt") return "DEBIAN_FRONTEND=noninteractive apt-get install -y";
253	  if (which === "dnf") return "dnf install -y";
254	  if (which === "yum") return "yum install -y";
255	  throw new Error("No supported package manager (apt-get/dnf/yum) found on the server.");
256	}
