116	// ---- Timeouts -------------------------------------------------------------
117	const CONNECT_TIMEOUT_MS = 20_000;
118	const SETUP_TIMEOUT_MS = 60_000; // small writes, checks
119	const INSTALL_TIMEOUT_MS = 10 * 60_000; // package installs (apt/dnf can be slow)
120	const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump/import
