122	// ---- Strict allowlist validators (throw/reject on any violation) ----------
123	// Charsets below are deliberately shell-inert: no quotes, spaces, metachars or
124	// newlines. Validated values are therefore safe to interpolate into a command.
125	const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
126	const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
127	const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
128	const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
129	const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
130	// Docker volume name (docker's own charset) and systemd unit name — shell-inert.
131	const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
132	const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;
133	
134	// Top-level system locations we refuse to overwrite on the target even if a
135	// (validated) path points at one — a lift-and-shift must never clobber the new
136	// server's own OS. Docker volumes/state are handled by their dedicated steps.
137	const UNSAFE_PREFIXES = [
138	  "/bin", "/sbin", "/usr", "/lib", "/lib64", "/etc/systemd", "/proc", "/sys",
139	  "/dev", "/run", "/boot", "/var/lib/docker",
140	];
141	const UNSAFE_EXACT = new Set(["/", "/etc", "/var", "/var/lib", "/usr", "/home", "/root/.ssh"]);
142	
143	function assert(cond: unknown, msg: string): asserts cond {
144	  if (!cond) throw new Error(msg);
145	}
146	
147	function validHost(h: string): boolean {
148	  return typeof h === "string" && (HOSTNAME_RE.test(h) || IPV4_RE.test(h) || IPV6_RE.test(h));
149	}
150	
151	function validPath(p: string): boolean {
152	  return typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
153	}
154	
155	/** A validated path we are willing to rsync directly onto the target's real fs. */
156	function safeCopyTarget(p: string): boolean {
157	  if (!validPath(p)) return false;
158	  if (UNSAFE_EXACT.has(p)) return false;
159	  for (const pre of UNSAFE_PREFIXES) if (p === pre || p.startsWith(pre + "/")) return false;
160	  return true;
161	}
162	
163	/** dirname of a validated absolute path (both inputs/outputs are shell-inert). */
164	function parentDir(p: string): string {
165	  const i = p.lastIndexOf("/");
166	  return i <= 0 ? "/" : p.slice(0, i);
167	}
