169	// ---- SSH plumbing ---------------------------------------------------------
170	function execRemote(
171	  conn: Client,
172	  cmd: string,
173	  timeoutMs: number
174	): Promise<{ code: number; stdout: string; stderr: string }> {
175	  return new Promise((resolve, reject) => {
176	    conn.exec(cmd, (err, stream: ClientChannel) => {
177	      if (err) return reject(err);
178	      let stdout = "";
179	      let stderr = "";
180	      const timer = setTimeout(() => {
181	        try {
182	          stream.close();
183	        } catch {
184	          /* ignore */
185	        }
186	        reject(new Error("remote command timed out"));
187	      }, timeoutMs);
188	      stream
189	        .on("close", (code: number) => {
190	          clearTimeout(timer);
191	          resolve({ code: code ?? 0, stdout, stderr });
192	        })
193	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
194	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
195	    });
196	  });
197	}
