199	/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
200	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
201	  return new Promise((resolve, reject) => {
202	    const ws = sftp.createWriteStream(path, { mode: 0o600 });
203	    ws.on("close", () => resolve());
204	    ws.on("error", (e: Error) => reject(e));
205	    ws.end(Buffer.from(content, "utf8"));
206	  });
207	}
