209	function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
210	  return new Promise((resolve, reject) => {
211	    const target = connectionTarget(server as any);
212	    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
213	    const password = serverRootPassword(server);
214	    if (!password) return reject(new Error("target server has no root password on record"));
215	    const conn = new Client();
216	    conn.on("ready", () => {
217	      conn.sftp((err, sftp) => {
218	        if (err) return reject(err);
219	        resolve({ conn, sftp });
220	      });
221	    });
222	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
223	    conn.connect({
224	      host: target.host,
225	      port: target.port,
226	      username: "root",
227	      password,
228	      readyTimeout: CONNECT_TIMEOUT_MS,
229	    });
230	  });
231	}
