233	// ---- Prerequisite install (FIXED allowlist — never source-supplied) -------
234	type PkgKey = "docker" | "mysql" | "postgresql" | "nginx" | "apache" | "nodejs" | "python3";
235	
236	// Command that succeeds iff the package's main binary is already present.
237	const PKG_CHECK: Record<PkgKey, string> = {
238	  docker: "command -v docker >/dev/null 2>&1",
239	  mysql: "command -v mysql >/dev/null 2>&1 || command -v mariadb >/dev/null 2>&1",
240	  postgresql: "command -v psql >/dev/null 2>&1",
241	  nginx: "command -v nginx >/dev/null 2>&1",
242	  apache: "command -v apache2 >/dev/null 2>&1 || command -v httpd >/dev/null 2>&1",
243	  nodejs: "command -v node >/dev/null 2>&1",
244	  python3: "command -v python3 >/dev/null 2>&1",
245	};
246	// Debian/Ubuntu (apt) package strings — the primary target for Nxeon servers.
247	const PKG_APT: Record<PkgKey, string> = {
248	  docker: "docker.io docker-compose-plugin",
249	  mysql: "mariadb-server mariadb-client",
250	  postgresql: "postgresql",
251	  nginx: "nginx",
252	  apache: "apache2",
253	  nodejs: "nodejs npm",
254	  python3: "python3 python3-pip",
255	};
256	// RHEL/Fedora (dnf/yum) fallback package strings.
257	const PKG_DNF: Record<PkgKey, string> = {
258	  docker: "docker docker-compose-plugin",
259	  mysql: "mariadb-server mariadb",
260	  postgresql: "postgresql-server postgresql",
261	  nginx: "nginx",
262	  apache: "httpd",
263	  nodejs: "nodejs npm",
264	  python3: "python3 python3-pip",
265	};
266	// A friendly label for the log/summary.
267	const PKG_LABEL: Record<PkgKey, string> = {
268	  docker: "Docker Engine + compose",
269	  mysql: "MySQL/MariaDB server",
270	  postgresql: "PostgreSQL server",
271	  nginx: "nginx",
272	  apache: "Apache",
273	  nodejs: "Node.js",
274	  python3: "Python 3 + pip",
275	};
276	
277	/**
278	 * Idempotently ensure each allowlisted package is present on the target. Runs
279	 * `apt-get update` once, then for each key: skip if the check passes, else try
280	 * apt → dnf → yum with the FIXED package string. Returns which were newly
281	 * installed / already present / failed. Never throws (best-effort per package).
282	 */
283	async function ensurePackages(
284	  conn: Client,
285	  keys: PkgKey[]
286	): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
287	  const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
288	  if (keys.length === 0) return out;
289	  // Refresh apt metadata once (best-effort; ignored on non-apt systems).
290	  await execRemote(conn, `apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => {});
291	  for (const key of keys) {
292	    const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
293	    if (already) {
294	      out.push({ key, ok: true, already: true });
295	      continue;
296	    }
297	    // All three package strings are compile-time constants from the allowlist.
298	    const install =
299	      `DEBIAN_FRONTEND=noninteractive apt-get install -y ${PKG_APT[key]} ` +
300	      `|| dnf install -y ${PKG_DNF[key]} ` +
301	      `|| yum install -y ${PKG_DNF[key]}`;
302	    const r = await execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
303	    const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
304	    if (nowPresent) {
305	      out.push({ key, ok: true, already: false });
306	    } else {
307	      const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
308	      out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
309	    }
310	  }
311	  return out;
312	}
