314	// ---- Plan derivation (prefer explicit items, re-validate everything) ------
315	function derivePlan(items: Items) {
316	  const scan = items.scan ?? {};
317	
318	  // Engines to dump: explicit dbEngines, else engines the scan marked present.
319	  const engineSet = new Set<string>();
320	  for (const e of items.dbEngines ?? []) engineSet.add(e);
321	  if (engineSet.size === 0) for (const e of scan.engines ?? []) if (e?.present && e.engine) engineSet.add(e.engine);
322	  const dbEngines = [...engineSet].filter((e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres");
323	
324	  const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
325	  const composeDirs = [...new Set(items.composeDirs ?? [])].filter((p) => validPath(p)).slice(0, 40);
326	  const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
327	  const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
328	  const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
329	  const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
330	  const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
331	  const containers = (scan.containers ?? [])
332	    .map((c) => ({
333	      name: String(c?.name ?? ""),
334	      image: String(c?.image ?? ""),
335	      ports: String(c?.ports ?? ""),
336	      mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
337	    }))
338	    .slice(0, 30);
339	
340	  const prereqs: PkgKey[] = [];
341	  if (dbEngines.includes("mysql")) prereqs.push("mysql");
342	  if (dbEngines.includes("postgres")) prereqs.push("postgresql");
343	  if (hasContainers) prereqs.push("docker");
344	  for (const w of webServers) prereqs.push(w === "nginx" ? "nginx" : "apache");
345	  for (const rt of runtimes) prereqs.push(rt);
346	
347	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes, services, containers, prereqs };
348	}
