352	/**
353	 * Perform a real lift-and-shift migration. Throws only on a FATAL setup error
354	 * (validation / target connect); every migration sub-step is best-effort and
355	 * records its outcome in the returned summary instead of aborting the run.
356	 */
357	export async function runRealMigration(input: RealMigrationInput): Promise<RealMigrationSummary> {
358	  const { migration, target, items, report } = input;
359	  assert(target, "target server row not found");
360	
361	  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
362	  const host = migration.sourceHost;
363	  const port = migration.sourcePort;
364	  const user = migration.sourceUser;
365	  assert(validHost(host), "source host is not a valid hostname or IP address");
366	  assert(Number.isInteger(port) && port >= 1 && port <= 65535, "source SSH port is out of range");
367	  assert(USER_RE.test(user), "source username contains unsupported characters");
368	
369	  const rawPaths = (items.paths ?? []).map((p) => p.trim()).filter(Boolean);
370	  for (const p of rawPaths) assert(validPath(p), `unsupported file path: ${p}`);
371	  // Direct-to-real-path copy: refuse to overwrite the target's own OS locations.
372	  const paths = rawPaths.filter(safeCopyTarget);
373	
374	  const plan = derivePlan(items);
375	  for (const p of plan.composeDirs) assert(safeCopyTarget(p), `unsupported compose dir: ${p}`);
376	
377	  assert(paths.length || plan.dbEngines.length || plan.composeDirs.length || plan.dockerVolumes.length, "nothing selected to migrate");
378	
379	  // Root-vs-sudo prefix for privileged commands ON THE SOURCE (constant strings).
380	  const priv = user === "root" ? "" : "sudo -n ";
381	
382	  // ---- 2. Decrypt the ONE secret we still need (source SSH password) ------
383	  const sshPass = decryptSecret(migration.sourcePasswordEnc);
384	  assert(sshPass, "source SSH password is missing or could not be decrypted");
385	
386	  // ---- 3. Connect to the TARGET (our own server) --------------------------
387	  await report(6, "Connecting…", "Connecting to your Nxeon server to prepare the lift-and-shift.");
388	  const { conn, sftp } = await connectTarget(target!);
389	
390	  const work = `/root/nxeon-migrations/${migration.id}`;
391	  const passFile = `${work}/ssh.pass`;
392	  const knownHosts = `${work}/known_hosts`;
393	  const sshOpts =
394	    `-p ${port} -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile=${knownHosts} ` +
395	    `-o ConnectTimeout=25 -o PreferredAuthentications=password -o PubkeyAuthentication=no`;
396	  const srcSpec = `${user}@${host}`;
397	  // rsync pull from the source over the sshpass-driven ssh (used everywhere below).
398	  const rsyncPull = (remotePath: string, localParent: string) =>
399	    `sshpass -f ${passFile} rsync -az --numeric-ids --timeout=1200 -e 'ssh ${sshOpts}' ${srcSpec}:${remotePath} ${localParent}/`;
400	  // Run a fixed command ON THE SOURCE and capture its output on the target.
401	  const onSource = (cmd: string) => `sshpass -f ${passFile} ssh ${sshOpts} ${srcSpec} '${cmd}'`;
402	
403	  const results: MigrationStepResult[] = [];
404	  const verifiedRunning: string[] = [];
405	  const needsAttention: string[] = [];
406	  const push = (r: MigrationStepResult) => {
407	    results.push(r);
408	    if (r.status === "running") verifiedRunning.push(r.step);
409	    else if (r.status === "copied" || r.status === "failed") needsAttention.push(`${r.step} — ${r.detail}`);
410	  };
411	
412	  try {
413	    // ---- 4. Prepare the target: transfer tools + work dir + secret file ----
414	    await report(10, "Preparing…", "Ensuring transfer tools (rsync, sshpass) are present on the target.");
415	    await execRemote(
416	      conn,
417	      `command -v rsync >/dev/null 2>&1 && command -v sshpass >/dev/null 2>&1 || ` +
418	        `{ (apt-get update -y && apt-get install -y rsync sshpass) || (dnf install -y rsync sshpass) || (yum install -y rsync sshpass); }`,
419	      INSTALL_TIMEOUT_MS
420	    );
421	    const tools = await execRemote(conn, `command -v rsync && command -v sshpass`, SETUP_TIMEOUT_MS);
422	    assert(tools.code === 0, "could not install rsync/sshpass on the target server");
423	
424	    await execRemote(
425	      conn,
426	      `mkdir -p ${work}/dumps && chmod 700 ${work} && touch ${knownHosts} && chmod 600 ${knownHosts}`,
427	      SETUP_TIMEOUT_MS
428	    );
429	    // Write the source SSH password to a 0600 file over SFTP (never a shell arg).
430	    await sftpWrite(sftp, passFile, sshPass);
431	
432	    // ---- 5. Install prerequisites on the target (fixed allowlist) ---------
433	    if (plan.prereqs.length) {
434	      await report(16, "Installing prerequisites…", `Preparing the target: ${plan.prereqs.map((k) => PKG_LABEL[k]).join(", ")}.`);
435	      const installed = await ensurePackages(conn, plan.prereqs);
436	      for (const r of installed) {
437	        if (r.ok) {
438	          push({ step: `Install ${PKG_LABEL[r.key]}`, status: "running", detail: r.already ? "already present" : "installed" });
439	          await report(18, "Installing prerequisites…", `  ${PKG_LABEL[r.key]}: ${r.already ? "already present" : "installed"}.`);
440	        } else {
441	          push({ step: `Install ${PKG_LABEL[r.key]}`, status: "failed", detail: r.err ?? "install failed" });
442	          await report(18, "Installing prerequisites…", `  ${PKG_LABEL[r.key]}: could not install — ${r.err ?? "unknown error"}.`);
443	        }
444	      }
445	      // Make sure DB engines + docker daemon are actually up before we use them.
446	      if (plan.dbEngines.includes("mysql"))
447	        await execRemote(conn, `systemctl enable --now mariadb 2>/dev/null || systemctl enable --now mysql 2>/dev/null || service mysql start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
448	      if (plan.dbEngines.includes("postgres"))
449	        await execRemote(conn, `systemctl enable --now postgresql 2>/dev/null || service postgresql start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
450	      if (plan.hasContainers)
451	        await execRemote(conn, `systemctl enable --now docker 2>/dev/null || service docker start 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
452	    }
453	
454	    // ---- 6. Files: rsync each selected path to the SAME path on target ----
455	    if (paths.length) {
456	      await report(28, "Copying files…", `Copying ${paths.length} path(s) from ${srcSpec} to the same locations on the new server.`);
457	      let idx = 0;
458	      let copied = 0;
459	      for (const p of paths) {
460	        idx++;
461	        const destParent = parentDir(p);
462	        await execRemote(conn, `mkdir -p ${destParent}`, SETUP_TIMEOUT_MS);
463	        const pct = 28 + Math.round((idx / paths.length) * 22); // 28 → 50
464	        await report(pct, "Copying files…", `  rsync ${p} → ${p}`);
465	        const r = await execRemote(conn, rsyncPull(p, destParent), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
466	        if (r.code === 0) {
467	          copied++;
468	        } else {
469	          const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
470	          push({ step: `Copy ${p}`, status: "failed", detail: tail || `rsync exit ${r.code}` });
471	          await report(pct, "Copying files…", `  copy failed for ${p}: ${tail || `rsync exit ${r.code}`}`);
472	        }
473	      }
474	      if (copied) push({ step: `Copy ${copied} folder(s) to their original paths`, status: "copied", detail: "files placed at the same paths on the new server" });
475	    }
476	
477	    // ---- 7. Named Docker volume data --------------------------------------
478	    if (plan.dockerVolumes.length) {
479	      await report(52, "Copying container data…", `Copying ${plan.dockerVolumes.length} named Docker volume(s).`);
480	      let ok = 0;
481	      for (const v of plan.dockerVolumes) {
482	        // Create the volume (idempotent), then rsync its _data into place.
483	        await execRemote(conn, `docker volume create ${v} >/dev/null 2>&1 || true`, SETUP_TIMEOUT_MS).catch(() => {});
484	        const dataDir = `/var/lib/docker/volumes/${v}/_data`;
485	        await execRemote(conn, `mkdir -p ${dataDir}`, SETUP_TIMEOUT_MS).catch(() => {});
486	        const r = await execRemote(conn, rsyncPull(`${dataDir}`, `/var/lib/docker/volumes/${v}`), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
487	        if (r.code === 0) ok++;
488	        else {
489	          const tail = (r.stderr || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
490	          push({ step: `Copy volume ${v}`, status: "failed", detail: tail || `rsync exit ${r.code}` });
491	        }
492	      }
493	      if (ok) push({ step: `Copy ${ok} Docker volume(s)`, status: "copied", detail: "volume data restored under /var/lib/docker/volumes" });
494	    }
495	
496	    // ---- 8. Databases: dump via source root LOCAL auth, import on target ---
497	    for (const engine of plan.dbEngines) {
498	      await report(60, "Migrating databases…", `Dumping ${engine === "postgres" ? "PostgreSQL" : "MySQL/MariaDB"} from the source (root, no password).`);
499	      if (engine === "mysql") {
500	        const dump = `${work}/dumps/mysql-all.sql`;
501	        // mysqldump over root's LOCAL socket auth (Debian/Ubuntu root = auth_socket).
502	        const dumpCmd = `${priv}mysqldump --single-transaction --routines --triggers --events --all-databases`;
503	        const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/mysql.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
504	        const nonEmpty = await execRemote(conn, `test -s ${dump}`, SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
505	        if (r.code !== 0 || !nonEmpty) {
506	          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/mysql.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
507	          push({ step: "Migrate MySQL/MariaDB", status: "failed", detail: `root could not dump via local socket${err ? `: ${err}` : ""} — import skipped` });
508	          await report(62, "Migrating databases…", `  MySQL dump via root failed — skipping (databases left for manual export).`);
509	        } else {
510	          // Import on the target as its own root (socket auth — no password).
511	          const imp = await execRemote(conn, `mysql < ${dump} 2>${work}/dumps/mysql-import.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
512	          if (imp.code === 0) {
513	            push({ step: "Migrate MySQL/MariaDB databases", status: "copied", detail: "dumped via source root socket and imported on the target" });
514	            await report(64, "Migrating databases…", `  MySQL databases dumped and imported.`);
515	          } else {
516	            const err = await execRemote(conn, `tail -c 200 ${work}/dumps/mysql-import.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
517	            push({ step: "Import MySQL/MariaDB", status: "failed", detail: `dump succeeded but import failed${err ? `: ${err}` : ""} — dump kept at ${dump}` });
518	          }
519	        }
520	      } else {
521	        const dump = `${work}/dumps/postgres-all.sql`;
522	        // pg_dumpall over peer auth as the postgres superuser.
523	        const dumpCmd = user === "root" ? "sudo -u postgres pg_dumpall" : "sudo -n -u postgres pg_dumpall";
524	        const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/pg.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
525	        const nonEmpty = await execRemote(conn, `test -s ${dump}`, SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
526	        if (r.code !== 0 || !nonEmpty) {
527	          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/pg.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
528	          push({ step: "Migrate PostgreSQL", status: "failed", detail: `postgres peer dump failed${err ? `: ${err}` : ""} — import skipped` });
529	          await report(62, "Migrating databases…", `  PostgreSQL dump via peer auth failed — skipping.`);
530	        } else {
531	          const imp = await execRemote(conn, `sudo -u postgres psql -f ${dump} >/dev/null 2>${work}/dumps/pg-import.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
532	          // pg_dumpall + psql exits 0 even with benign "role already exists" notices.
533	          if (imp.code === 0) {
534	            push({ step: "Migrate PostgreSQL databases", status: "copied", detail: "dumped via source postgres peer auth and imported on the target" });
535	            await report(64, "Migrating databases…", `  PostgreSQL databases dumped and imported.`);
536	          } else {
537	            const err = await execRemote(conn, `tail -c 200 ${work}/dumps/pg-import.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
538	            push({ step: "Import PostgreSQL", status: "failed", detail: `dump succeeded but import reported errors${err ? `: ${err}` : ""} — dump kept at ${dump}` });
539	          }
540	        }
541	      }
542	    }
543	
544	    // ---- 9. Docker Compose bring-up ---------------------------------------
545	    if (plan.composeDirs.length) {
546	      await report(74, "Starting containers…", `Bringing up ${plan.composeDirs.length} Docker Compose project(s).`);
547	      for (const dir of plan.composeDirs) {
548	        // dir has already been copied to the same path in step 6 (or is being copied).
549	        const r = await execRemote(
550	          conn,
551	          `sh -c 'cd ${dir} && { docker compose up -d || docker-compose up -d; }' >/dev/null 2>${work}/dumps/compose.err`,
552	          TRANSFER_TIMEOUT_MS
553	        ).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
554	        if (r.code === 0) {
555	          push({ step: `Compose up ${dir}`, status: "running", detail: "docker compose up -d succeeded" });
556	          await report(78, "Starting containers…", `  compose up in ${dir}: started.`);
557	        } else {
558	          const err = await execRemote(conn, `tail -c 200 ${work}/dumps/compose.err 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim()).catch(() => "");
559	          push({ step: `Compose up ${dir}`, status: "failed", detail: `could not start${err ? `: ${err}` : ""} — run 'docker compose up -d' in ${dir}` });
560	          await report(78, "Starting containers…", `  compose up in ${dir} failed — left for manual start.`);
561	        }
562	      }
563	    }
564	    // Standalone (non-compose) containers: log a run-equivalent, never auto-run
565	    // an arbitrary source-supplied image. Honest — these are left for the user.
566	    for (const c of plan.containers) {
567	      if (!c.name || !c.image) continue;
568	      const portsHint = c.ports ? ` ports[${c.ports}]` : "";
569	      const mountsHint = c.mounts.length ? ` mounts[${c.mounts.join(",")}]` : "";
570	      push({
571	        step: `Container ${c.name}`,
572	        status: "copied",
573	        detail: `recreate on the new server: image ${c.image}${portsHint}${mountsHint}`,
574	      });
575	    }
576	
577	    // ---- 10. Web-server vhosts (best-effort copy + reload) ----------------
578	    for (const w of plan.webServers) {
579	      if (w === "nginx") {
580	        await execRemote(conn, `mkdir -p /etc/nginx`, SETUP_TIMEOUT_MS).catch(() => {});
581	        const r = await execRemote(conn, rsyncPull("/etc/nginx/", "/etc/nginx"), TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
582	        if (r.code === 0) {
583	          const up = await execRemote(conn, `nginx -t 2>/dev/null && (systemctl reload nginx 2>/dev/null || systemctl restart nginx 2>/dev/null)`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
