593	          const up = await execRemote(conn, `apachectl configtest 2>/dev/null && (systemctl reload apache2 2>/dev/null || systemctl restart apache2 2>/dev/null)`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
