610	          push({ step: `Service ${svc}`, status: "copied", detail: "unit not a simple /etc/systemd/system file — re-enable manually" });
611	          continue;
612	        }
613	        await execRemote(conn, `systemctl daemon-reload 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
614	        const en = await execRemote(conn, `systemctl enable --now ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
615	        const active = await execRemote(conn, `systemctl is-active ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim() === "active").catch(() => false);
616	        if (en.code === 0 && active) push({ step: `Service ${svc}`, status: "running", detail: "unit copied, enabled and active" });
617	        else push({ step: `Service ${svc}`, status: "copied", detail: "unit copied but not confirmed active — check `systemctl status`" });
618	      }
619	    }
