622	    await report(92, "Verifying…", "Checking that databases, containers and services are up on the new server.");
623	    if (plan.dbEngines.includes("mysql")) {
624	      const up = await execRemote(conn, `systemctl is-active mariadb 2>/dev/null || systemctl is-active mysql 2>/dev/null || pgrep -x mysqld >/dev/null 2>&1 && echo active`, SETUP_TIMEOUT_MS).then((x) => /active/.test(x.stdout)).catch(() => false);
625	      push({ step: "MySQL/MariaDB engine", status: up ? "running" : "copied", detail: up ? "engine is active on the target" : "engine not confirmed active — start it manually" });
626	    }
627	    if (plan.dbEngines.includes("postgres")) {
628	      const up = await execRemote(conn, `systemctl is-active postgresql 2>/dev/null || (pgrep -x postgres >/dev/null 2>&1 && echo active)`, SETUP_TIMEOUT_MS).then((x) => /active/.test(x.stdout)).catch(() => false);
629	      push({ step: "PostgreSQL engine", status: up ? "running" : "copied", detail: up ? "engine is active on the target" : "engine not confirmed active — start it manually" });
630	    }
631	    if (plan.hasContainers) {
632	      const n = await execRemote(conn, `docker ps -q 2>/dev/null | wc -l`, SETUP_TIMEOUT_MS).then((x) => parseInt(x.stdout.trim(), 10) || 0).catch(() => 0);
633	      push({ step: "Docker containers", status: n > 0 ? "running" : "copied", detail: n > 0 ? `${n} container(s) running on the target` : "no containers running yet — start your compose project(s)" });
634	      await report(94, "Verifying…", `  docker ps shows ${n} running container(s).`);
635	    }
636	    if (plan.verifyPorts.length) {
637	      const list = plan.verifyPorts.join(" ");
638	      const out = await execRemote(
639	        conn,
640	        `for p in ${list}; do (ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | grep -q ":$p " && echo "$p up" || echo "$p down"; done`,
641	        SETUP_TIMEOUT_MS
642	      ).then((x) => x.stdout).catch(() => "");
643	      const upPorts = (out.match(/(\d+) up/g) ?? []).map((s) => s.replace(" up", ""));
644	      const downPorts = (out.match(/(\d+) down/g) ?? []).map((s) => s.replace(" down", ""));
645	      if (upPorts.length) push({ step: "Listening ports", status: "running", detail: `now listening on the target: ${upPorts.join(", ")}` });
646	      if (downPorts.length) push({ step: "Ports not yet listening", status: "copied", detail: `not up on the target yet: ${downPorts.join(", ")} — start the owning app/service` });
647	      await report(95, "Verifying…", `  ports up: ${upPorts.join(", ") || "none"}; not up: ${downPorts.join(", ") || "none"}.`);
648	    }
649	
650	    // ---- 13. Final honest summary ----------------------------------------
651	    await report(
652	      97,
653	      "Finalising…",
654	      `Migrated & running (verified): ${verifiedRunning.length}. Copied — may need a manual step: ${needsAttention.length}.`
655	    );
656	    if (needsAttention.length) {
657	      await report(98, "Finalising…", `Needs a manual step: ${needsAttention.slice(0, 8).join(" | ")}${needsAttention.length > 8 ? " …" : ""}`);
658	    }
659	
660	    return { results, verifiedRunning, needsAttention };
661	  } finally {
662	    // Scrub the SSH password file from the target, always. DB dumps under
663	    // ${work}/dumps are intentionally kept so a failed import can be retried by hand.
664	    await execRemote(conn, `shred -u ${passFile} 2>/dev/null || rm -f ${passFile}`, SETUP_TIMEOUT_MS).catch(() => {});
665	    try {
666	      conn.end();
667	    } catch {
668	      /* best-effort */
669	    }
670	  }
671	}
