133	export async function runMigration(job: Job): Promise<void> {
134	  const migration = await loadMigration(job);
135	  const items = (migration.items ?? {}) as MigrationItems;
136	  const paths = items.paths ?? [];
137	  const target = migration.server;
138	  const targetName = target ? target.label || target.hostname : "your server";
139	
140	  // Fresh start (also lets a retried job re-enter cleanly).
141	  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
142	  await db.migration.update({
143	    where: { id: migration.id },
144	    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
145	  });
146	
147	  // Shared progress reporter: threads the bounded log tail through each update so
148	  // both the real engine and the simulation write to the same Migration row.
149	  const reportStep = async (progress: number, step: string, line: string) => {
150	    log = await report(migration.id, progress, step, line, log);
151	  };
152	
153	  try {
154	    if (REAL_MIGRATION) {
155	      // ---- REAL lift-and-shift (hardened; opt-in via ENABLE_REAL_MIGRATION) --
156	      const summary = await runRealMigration({
157	        migration: {
158	          id: migration.id,
159	          sourceHost: migration.sourceHost,
160	          sourcePort: migration.sourcePort,
161	          sourceUser: migration.sourceUser,
162	          sourcePasswordEnc: migration.sourcePasswordEnc,
163	        },
164	        target: target as any,
165	        items,
166	        report: reportStep,
167	      });
168	
169	      await db.migration.update({
170	        where: { id: migration.id },
171	        data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
172	      });
173	      // Persist the honest step-by-step summary (secret-free) into items.results.
174	      await clearSecrets(migration.id, items, summary.results);
175	
176	      const workDir = migrationWorkDir(migration.id);
177	      const running = summary.verifiedRunning.length;
178	      const manual = summary.needsAttention.length;
179	      const body =
180	        `Lift-and-shift onto ${targetName} finished. ${running} item(s) migrated & verified running; ` +
181	        `${manual} copied that may need a manual step. ` +
182	        (manual ? `To finish: ${summary.needsAttention.slice(0, 5).join(" | ")}${manual > 5 ? " …" : ""}. ` : "") +
183	        `Any DB dumps that couldn't import were kept under ${workDir}/dumps. Point your DNS at the new server when ready.`;
184	      await notify(migration.userId, `Migration to ${targetName} completed`, body, "/dashboard/migrate");
185	      return;
186	    }
187	
188	    // ---- Progress-reporting SIMULATION of the lift-and-shift (default) --------
189	    // Mirrors the real engine's flow (dump DBs via root, install prerequisites,
190	    // import DBs, compose up, verify) with SYNTHETIC success. Delays are short so
191	    // the UI polls a live-feeling progression. NEVER opens a real SSH connection.
192	    const dbEngines = (items.dbEngines ?? []).filter((e) => e === "mysql" || e === "postgres");
193	    const composeDirs = items.composeDirs ?? [];
194	    const webServers = items.webServers ?? [];
195	    const runtimes = items.runtimes ?? [];
196	    const verifyPorts = items.verifyPorts ?? [];
197	    const hasContainers = !!items.hasContainers || composeDirs.length > 0;
198	    const simResults: MigrationStepResult[] = [];
199	
