202	    await reportStep(12, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort}). Authenticated with root.`);
203	    await sleep(SANDBOX ? 400 : 800);
204	
205	    // Prerequisites stage.
206	    const prereqLabels: string[] = [];
