256	    }
257	    if (verifyPorts.length) {
258	      await reportStep(95, "Verifying…", `  ports up: ${verifyPorts.join(", ")}.`);
259	      simResults.push({ step: "Listening ports", status: "running", detail: `now listening: ${verifyPorts.join(", ")}` });
260	    }
261	
262	    const simRunning = simResults.filter((r) => r.status === "running").length;
263	    const simManual = simResults.filter((r) => r.status === "copied" || r.status === "failed").length;
264	    await reportStep(98, "Finalising…", `Migrated & running (verified): ${simRunning}. Copied — may need a manual step: ${simManual}.`);
265	    await sleep(SANDBOX ? 300 : 600);
266	
267	    await db.migration.update({
268	      where: { id: migration.id },
269	      data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
270	    });
271	    // Security: drop all source credentials now that the job is done; persist summary.
272	    await clearSecrets(migration.id, items, simResults);
273	
274	    await notify(
275	      migration.userId,
276	      `Migration to ${targetName} completed`,
277	      `Lift-and-shift onto ${targetName} finished: ${simRunning} item(s) migrated & running, ${simManual} copied. Point your DNS at the new server when ready.`,
278	      "/dashboard/migrate"
279	    );
280	  } catch (e: any) {
281	    const lastError = `${e?.message ?? e}`.slice(0, 1000);
282	    console.error(`[migrate] migration ${migration.id} failed:`, e);
283	    log = appendLog(log, `ERROR: ${lastError}`);
284	    await db.migration
285	      .update({
286	        where: { id: migration.id },
287	        data: { status: "FAILED", step: "Failed", lastError, log, finishedAt: new Date() },
288	      })
289	      .catch(() => {});
290	    // Security: clear the stored source password/DB secrets even on failure.
291	    await clearSecrets(migration.id, items).catch(() => {});
292	    await notify(
293	      migration.userId,
294	      `Migration to ${targetName} failed`,
295	      lastError,
296	      "/dashboard/migrate"
297	    );
298	    // Swallow — the failure is recorded on the Migration row. Re-throwing would
299	    // make the job loop retry a migration whose secrets we've already cleared.
300	  }
