import { SANDBOX } from "./sandbox";
import { withServerSsh, exec, QUICK_TIMEOUT_MS } from "./ssh-exec";
import { detectSource, syntheticScan, parseSizeLabel, type ScanResult } from "../worker/migrate-detect";

const GiB = 1024 ** 3;

/**
 * Sum (in bytes) of the SELECTED migration items, plus the DB data-dir estimate
 * when a database engine was detected (databases are auto-included). Sizes come
 * from the read-only scan's human size labels; unknown-size items (custom folders,
 * Docker mounts) count as 0. Used both for the client storage panel and the
 * worker pre-flight — computed server-side here so the stored total is trusted.
 */
function selectedMigrationBytes(scan: ScanResult | undefined, selectedPaths: string[]): number {
  if (!scan || !scan.ok) return 0;
  const sizeByPath = new Map<string, number>();
  for (const w of scan.webRoots ?? []) sizeByPath.set(w.path, parseSizeLabel(w.sizeLabel));
  for (const h of scan.homes ?? []) sizeByPath.set(h.path, parseSizeLabel(h.sizeLabel));
  for (const a of scan.appDirs ?? []) sizeByPath.set(a.path, parseSizeLabel(a.sizeLabel));
  let total = 0;
  for (const p of selectedPaths) total += sizeByPath.get(p) ?? 0;
  // Databases are auto-included whenever an engine is present.
  const enginePresent = (scan.engines ?? []).some((e) => e.present);
  if (enginePresent) total += Math.max(0, scan.dbSizeBytes ?? 0);
  return Math.round(total);
}

/** Parse ID / VERSION_ID / PRETTY_NAME lines from `/etc/os-release` (never sourced). */
function parseOsRelease(stdout: string): { id: string; versionId: string; pretty: string } | null {
  const o: Record<string, string> = {};
  for (const line of (stdout ?? "").split("\n")) {
    const m = /^(ID|VERSION_ID|PRETTY_NAME)=(.*)$/.exec(line.trim());
    if (!m) continue;
    o[m[1]] = m[2].trim().replace(/^["']|["']$/g, "").slice(0, 128);
  }
  if (!o.ID && !o.PRETTY_NAME && !o.VERSION_ID) return null;
  return {
    id: (o.ID ?? "").toLowerCase().slice(0, 32),
    versionId: (o.VERSION_ID ?? "").slice(0, 32),
    pretty: o.PRETTY_NAME ?? "",
  };
}

