export type TargetInfo = {
  /** null when the server is unreachable / df couldn't be parsed → soft warning. */
  disk: { totalBytes: number; usedBytes: number; availBytes: number } | null;
  os: { id: string; versionId: string; pretty: string } | null;
  arch: string | null;
};

/**
 * Probe a destination Nxeon server (owner-only) for its root-filesystem free
 * space and OS/architecture, so the wizard can show the storage headroom and the
 * OS-compatibility guardrail. Read-only: `df -B1`, `uname -m`, and a grep of
 * `/etc/os-release`. In SANDBOX returns synthetic values (never opens SSH).
 *
 * Failure is graceful: if the server is unreachable or df can't be parsed we
 * return `disk: null` (the UI shows "couldn't read free space" and allows the
 * migration with a soft warning rather than a hard block). OS falls back to the
 * server's known OS template; arch defaults to x86_64 (all our VMs are x86_64).
 */
export async function targetDiskFree(
  serverId: string
): Promise<{ error?: string; info?: TargetInfo }> {
  const { server } = await ownedTargetServer(serverId);

  // OS fallback from the known OS template (works even if the box is unreachable).
  const tmpl = await db.osTemplate
    .findUnique({ where: { id: server.osTemplateId }, select: { family: true, version: true, name: true } })
    .catch(() => null);
  const osFallback = tmpl
    ? {
        id: (tmpl.family || "linux").toLowerCase(),
        versionId: tmpl.version || "",
        pretty: `${tmpl.name}${tmpl.version ? ` ${tmpl.version}` : ""}`,
      }
    : null;

  if (SANDBOX) {
    // Synthetic 80 GB disk with ~63 GB free, matching our default plan sizing.
    return {
      info: {
        disk: { totalBytes: 80 * GiB, usedBytes: 17 * GiB, availBytes: 63 * GiB },
        os: osFallback ?? { id: "ubuntu", versionId: "24.04", pretty: "Ubuntu 24.04 LTS" },
        arch: "x86_64",
      },
    };
  }

  // Need dedicatedIp to compute the SSH connection target (dedicated → :22).
  const full = await db.server.findUnique({
    where: { id: server.id },
    include: { dedicatedIp: true },
  });

  try {
    const info = await withServerSsh(full as any, async (conn) => {
      // Root filesystem size/used/avail in bytes.
      const dfr = await exec(
        conn,
        "df -B1 --output=size,used,avail / 2>/dev/null | tail -n1",
        QUICK_TIMEOUT_MS
      );
      const nums = (dfr.stdout || "").trim().split("\n").pop()?.trim().split(/\s+/).map(Number) ?? [];
      let disk: TargetInfo["disk"] = null;
      if (nums.length >= 3 && nums.slice(0, 3).every((n) => Number.isFinite(n) && n > 0)) {
        disk = { totalBytes: nums[0], usedBytes: nums[1], availBytes: nums[2] };
      }
      const un = await exec(conn, "uname -m 2>/dev/null", QUICK_TIMEOUT_MS).catch(() => ({ stdout: "" }) as any);
      const arch = ((un.stdout as string) || "").trim().replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32) || null;
      const osr = await exec(
        conn,
        "grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null || true",
        QUICK_TIMEOUT_MS
      ).catch(() => ({ stdout: "" }) as any);
      const os = parseOsRelease((osr.stdout as string) || "") ?? osFallback;
      return { disk, os, arch: arch ?? "x86_64" };
    });
    return { info };
  } catch {
    // Unreachable / probe error → soft warning (no hard block).
    return { info: { disk: null, os: osFallback, arch: "x86_64" } };
  }
}

