// ---- Storage-guardrail helpers --------------------------------------------
const GiB = 1024 ** 3;

/** Parse a human size label ("1.2G", "340M", "220 MB") into bytes. Mirrors the
 *  server's parseSizeLabel — kept local so the client never imports the ssh2-laden
 *  detection module. */
function parseSize(label: string): number {
  const m = /^([\d.]+)\s*([KMGT]?)/i.exec((label ?? "").trim());
  if (!m) return 0;
  const n = parseFloat(m[1]);
  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
  return n * (mult[m[2].toUpperCase()] ?? 1);
}

/** Adaptive size formatter: GB for ≥1 GB, else MB. */
function fmtSize(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return "0 MB";
  const g = bytes / GiB;
  if (g >= 1) return g >= 10 ? `${g.toFixed(0)} GB` : `${g.toFixed(1)} GB`;
  const mb = bytes / (1024 * 1024);
  return `${Math.max(1, Math.round(mb))} MB`;
}

// ---- OS/architecture compatibility helpers --------------------------------
/** Collapse arch aliases so amd64≡x86_64 and arm64≡aarch64 compare equal. */
function normArch(a: string | null | undefined): string {
  const s = (a ?? "").toLowerCase();
  if (!s) return "";
  if (["x86_64", "amd64", "x64"].includes(s)) return "x86_64";
  if (["aarch64", "arm64"].includes(s)) return "arm64";
  if (s.startsWith("armv") || s === "armhf" || s === "arm") return "arm";
  if (["i386", "i686", "x86"].includes(s)) return "x86";
  return s;
}

const FAMILY_IDS: Record<string, string[]> = {
  debian: ["debian", "ubuntu", "linuxmint", "pop", "raspbian", "devuan", "kali", "elementary", "zorin"],
  rhel: ["rhel", "centos", "almalinux", "rocky", "fedora", "ol", "oracle", "amzn", "scientific", "cloudlinux"],
  suse: ["opensuse", "opensuse-leap", "opensuse-tumbleweed", "sles", "suse"],
  arch: ["arch", "manjaro", "endeavouros"],
  alpine: ["alpine"],
};
const FAMILY_LABEL: Record<string, string> = {
  debian: "Debian / Ubuntu",
  rhel: "RHEL / CentOS / Alma / Rocky",
  suse: "openSUSE / SLES",
  arch: "Arch",
  alpine: "Alpine",
  other: "another",
};
/** Map an os-release ID (or an osTemplate family string) to a distro family key. */
function familyOf(id: string | null | undefined): string {
  const s = (id ?? "").toLowerCase();
  if (!s) return "";
  for (const [fam, ids] of Object.entries(FAMILY_IDS)) if (ids.includes(s)) return fam;
  return "other";
}

/** Pick the closest OS template to the source distro: same family first (prefer a
 *  matching major version), else nothing. Returns the template or null. */
function closestOsTemplate(
  sourceId: string,
  sourceVersion: string,
  templates: OsTemplateOption[]
): OsTemplateOption | null {
  const fam = familyOf(sourceId);
  if (!fam || fam === "other") return null;
  const sameFamily = templates.filter((t) => familyOf(t.family) === fam);
  if (sameFamily.length === 0) return null;
  const srcMajor = (sourceVersion || "").split(".")[0];
  // Prefer an exact family + same-major-version match, else the same family.
  const exact = sameFamily.find((t) => (t.version || "").split(".")[0] === srcMajor && srcMajor);
  return exact ?? sameFamily[0];
}

type StorageState = "comfortable" | "tight" | "wontfit" | "unknown";
type CompatItem = { level: "critical" | "warn" | "note"; title: string; body: React.ReactNode };

export function MigrationWizard({
  servers,
  osTemplates = [],
