  servers: ServerOption[];
  osTemplates?: OsTemplateOption[];
}) {

// Step 2 — detection results + selections
const [scan, setScan] = useState<ScanResult | null>(null);
// Target free-space + OS/arch probe (for storage & compatibility guardrails).
// undefined = not yet fetched; a value with disk:null = probe failed (soft warn).
const [targetInfo, setTargetInfo] = useState<TargetInfo | null | undefined>(undefined);

