// ---- Storage guardrail — total to migrate vs. target free space ----------
// Recomputes live as the customer checks/unchecks. Unknown-size items (custom
// folders, Docker mounts) contribute 0; the DB estimate is added whenever an
// engine is detected (databases are auto-included).
const totalBytes = useMemo(() => {
  if (!scan) return 0;
  const byPath = new Map<string, number>();
  scan.webRoots.forEach((w) => byPath.set(w.path, parseSize(w.sizeLabel)));
  scan.homes.forEach((h) => byPath.set(h.path, parseSize(h.sizeLabel)));
  scan.appDirs.forEach((a) => byPath.set(a.path, parseSize(a.sizeLabel)));
  let t = 0;
  for (const p of selectedPaths) t += byPath.get(p) ?? 0;
  if (detectedEngines.length > 0) t += Math.max(0, scan.dbSizeBytes ?? 0);
  return t;
}, [scan, selectedPaths, detectedEngines]);

const storage = useMemo(() => {
  const disk = targetInfo?.disk ?? null;
  if (!disk) {
    return { state: "unknown" as StorageState, avail: 0, total: 0, diskTotal: 0, used: 0, margin: 0, deficitGB: 0 };
  }
  const avail = disk.availBytes;
  // Leave headroom for the OS/overhead: the larger of 2 GB or 10% of free space.
  const margin = Math.max(2 * GiB, avail * 0.1);
  let state: StorageState;
  if (totalBytes > avail) state = "wontfit";
  else if (totalBytes + margin > avail) state = "tight";
  else state = "comfortable";
  // How much extra free space to reach a comfortable fit (cover data + margin).
  const deficitGB = Math.max(1, Math.ceil((totalBytes + margin - avail) / GiB));
  return { state, avail, total: totalBytes, diskTotal: disk.totalBytes, used: disk.usedBytes, margin, deficitGB };
