  const tgtArch = targetInfo?.arch ?? null;
  const tgtOs = targetInfo?.os ?? null;

  const sa = normArch(srcArch);
  const ta = normArch(tgtArch);
  const archMismatch = !!sa && !!ta && sa !== ta;

  const sFam = familyOf(srcOs?.id);
  const tFam = familyOf(tgtOs?.id);
  const familyMismatch = !!sFam && !!tFam && sFam !== tFam;
  const sameFamilyDiffMajor =
    !!sFam && sFam === tFam && !!srcOs?.versionId && !!tgtOs?.versionId &&
    srcOs.versionId.split(".")[0] !== tgtOs.versionId.split(".")[0];

  if (archMismatch) {
    items.push({
      level: "critical",
      title: `Different CPU architecture (${sa} → ${ta})`,
      body: (
        <>
          Your old server is <span className="font-mono">{sa}</span> but your Nxeon server is{" "}
          <span className="font-mono">{ta}</span>. Your files and database dumps still migrate fine, but{" "}
          <strong>compiled programs and Docker images built for {sa} will not run</strong> on {ta}. Check anything
          custom-compiled or containerised before relying on it.
