  }

  if (familyMismatch) {
    const suggestion = srcOs ? closestOsTemplate(srcOs.id, srcOs.versionId, osTemplates) : null;
    items.push({
      level: "warn",
      title: `Different OS family (${FAMILY_LABEL[sFam] ?? sFam} → ${FAMILY_LABEL[tFam] ?? tFam})`,
      body: (
        <>
          OS-level packages, service unit paths and config locations differ between these families. We install
          equivalents from our catalog where we can, but system services and custom-compiled apps may need manual
          setup afterwards. <strong>Docker containers, database dumps and plain files port across distros fine.</strong>
          {suggestion && (
            <>
              {" "}
              For the smoothest migration, consider reinstalling this Nxeon server with{" "}
              <a className="font-medium text-brand-300 underline hover:text-brand-200" href={`/dashboard/servers/${serverId}?tab=resize`}>
                {suggestion.name}
                {suggestion.version ? ` ${suggestion.version}` : ""}
              </a>{" "}
              so it matches your old server (this erases the new server — do it before you migrate).
            </>
          )}
        </>
      ),
    });
  } else if (sameFamilyDiffMajor) {
    items.push({
      level: "note",
      title: `Same OS family, different version (${srcOs!.pretty || srcOs!.versionId} → ${tgtOs!.pretty || tgtOs!.versionId})`,
      body: <>Same distro family, different major version — usually fine. Occasionally a package needs a newer/older build.</>,
    });
  }

  // MySQL vs MariaDB: we install MariaDB on the destination; MySQL dumps import
  // into it fine, but a few edge cases (auth plugins, specific storage engines)
  // can need attention.
  if (detectedEngines.includes("mysql")) {
    items.push({
      level: "note",
      title: "MySQL → MariaDB",
      body: <>We set up MariaDB on the new server. Your MySQL dump imports into MariaDB in almost all cases; a few edge cases (auth plugins, uncommon storage engines) may need a small tweak.</>,
    });
  }

  const allMatch =
    items.length === 0 && !!sa && !!ta && sa === ta && !!sFam && !!tFam && sFam === tFam;

  return { items, allMatch, haveTargetInfo: !!tgtOs || !!tgtArch };
}, [scan, targetInfo, osTemplates, serverId, detectedEngines]);

