          <p className="text-sm text-red-200">
            The data you selected ({fmtSize(total)}) is more than the free space on your server ({fmtSize(avail)}). You
            need about <span className="font-semibold">{deficitGB} GB more</span> to migrate this safely. Untick some
            items above, or add storage:
          </p>
          <a
            href={`/dashboard/servers/${serverId}?tab=resize`}
            className="mt-2 inline-flex items-center gap-2 rounded-lg bg-red-500/20 px-3 py-1.5 text-sm font-medium text-red-100 ring-1 ring-red-400/40 transition hover:bg-red-500/30"
          >
            Add more storage →
          </a>
          <p className="mt-2 text-[11px] text-red-300/80">
            Upgrade to a larger-disk plan on the Resize tab. A block-storage volume also works if you only need extra
            space for data.
          </p>
        </div>
      )}
      {state === "tight" && (
        <p className="mt-3 text-xs text-amber-200/90">
          This leaves little headroom on the new server. If you can, untick anything you don&apos;t need — or{" "}
          <a href={`/dashboard/servers/${serverId}?tab=resize`} className="font-medium text-amber-200 underline hover:text-amber-100">
            add more storage
          </a>{" "}
          for comfort.
        </p>
      )}
    </div>
  );
}

/** OS / architecture compatibility panel with honest, tiered warnings. */
function CompatibilityPanel({
  compat,
}: {
  compat: { items: CompatItem[]; allMatch: boolean; haveTargetInfo: boolean };
}) {
  if (compat.allMatch) {
    return (
      <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/[0.06] px-3 py-2.5">
        <p className="section-label mb-1 text-emerald-300">Compatibility</p>
        <p className="text-xs text-slate-300">Compatible — same OS family &amp; architecture.</p>
      </div>
    );
  }
  if (compat.items.length === 0) return null;

  const TONE: Record<CompatItem["level"], string> = {
    critical: "border-red-500/40 bg-red-500/[0.08] text-red-200",
    warn: "border-amber-500/30 bg-amber-500/[0.08] text-amber-100",
    note: "border-white/10 bg-white/[0.02] text-slate-300",
  };
  const LABEL: Record<CompatItem["level"], string> = { critical: "Important", warn: "Heads up", note: "Note" };

  return (
    <div>
      <p className="section-label mb-2">Compatibility</p>
      <div className="space-y-2">
        {compat.items.map((it, i) => (
          <div key={i} className={`rounded-xl border px-3 py-2.5 ${TONE[it.level]}`}>
            <p className="mb-0.5 text-xs font-semibold">
              <span className="mr-1.5 rounded-full bg-black/20 px-1.5 py-0.5 text-[10px] uppercase tracking-wide">
                {LABEL[it.level]}
              </span>
              {it.title}
            </p>
            <p className="text-[11px] leading-relaxed opacity-90">{it.body}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

